insert into public.documents (code,name,name_ta,issuing_authority,eligibility,supporting_docs,steps,online_url,online_portal_name,offline_process,alternatives,after_obtaining,applies_to,source_url) values
('income_certificate','Income Certificate','வருமானச் சான்றிதழ்','Revenue Department, Government of Tamil Nadu (issued by the Tahsildar / Deputy Tahsildar)','Residents of Tamil Nadu who need proof of annual family income.','{"Aadhaar or other identity proof","Family/smart ration card","Proof of income (salary slip or self-declaration as required)","Passport-size photograph"}','{"Visit the TN e-Sevai portal or a nearby Arasu e-Sevai centre.","Choose Revenue Department services and select Income Certificate.","Fill in applicant and family income details.","Upload the supporting documents and pay the service charge shown on the portal.","Note the application number to track status.","Download the digitally signed certificate once approved by the Revenue official."}','https://www.tnesevai.tn.gov.in/','TN e-Sevai','Apply at any Arasu e-Sevai centre / Common Service Centre, or approach the Taluk office.',null,'Keep a PDF and printed copy. Upload it on the scholarship or scheme portal where asked.','TN','https://www.tnesevai.tn.gov.in/'),
('community_certificate','Community Certificate','சாதிச் சான்றிதழ்','Revenue Department, Government of Tamil Nadu (Tahsildar / Revenue Divisional Officer depending on community)','Members of SC, ST, BC, MBC, DNC and other notified communities.','{"Aadhaar or identity proof","Family/smart ration card","Community certificate of parent or relative, if available","School transfer certificate showing community, if available"}','{"Visit the TN e-Sevai portal or an Arasu e-Sevai centre.","Select Revenue Department → Community Certificate.","Enter details and upload supporting documents.","Revenue officials may conduct a field verification.","Download the certificate after approval."}','https://www.tnesevai.tn.gov.in/','TN e-Sevai','Apply at an Arasu e-Sevai centre or the Taluk office.',null,'Use it for reserved-category scholarships and fee concessions.','TN','https://www.tnesevai.tn.gov.in/'),
('nativity_certificate','Nativity / Residence Certificate','இருப்பிடச் சான்றிதழ்','Revenue Department, Government of Tamil Nadu (Tahsildar)','Persons residing in Tamil Nadu who need proof of residence/nativity.','{"Aadhaar or identity proof","Address proof such as ration card","School records showing place of study, if required"}','{"Open the TN e-Sevai portal or visit an Arasu e-Sevai centre.","Select Revenue Department → Nativity / Residence Certificate.","Fill details and upload documents.","Track the application and download the certificate after approval."}','https://www.tnesevai.tn.gov.in/','TN e-Sevai','Apply at an Arasu e-Sevai centre or Taluk office.',null,null,'TN','https://www.tnesevai.tn.gov.in/'),
('first_graduate_certificate','First Graduate Certificate','முதல் பட்டதாரி சான்றிதழ்','Revenue Department, Government of Tamil Nadu (Tahsildar)','Students who will be the first graduate in their family.','{"Aadhaar","Family/smart ration card","Transfer certificate / mark sheets","Declaration that no family member is a graduate"}','{"Visit the TN e-Sevai portal or an Arasu e-Sevai centre.","Select Revenue Department → First Graduate Certificate.","Upload the supporting documents and submit.","Download the certificate after approval."}','https://www.tnesevai.tn.gov.in/','TN e-Sevai','Apply at an Arasu e-Sevai centre or Taluk office.',null,'Submit it to your college during admission or counselling to claim the first-graduate concession.','TN','https://www.tnesevai.tn.gov.in/'),
('aadhaar','Aadhaar Card','ஆதார் அட்டை','Unique Identification Authority of India (UIDAI)','All residents of India.','{"Proof of identity","Proof of address","Proof of date of birth (as per UIDAI list of accepted documents)"}','{"Book an appointment on the myAadhaar portal or walk in to an Aadhaar Enrolment Centre.","Carry original supporting documents.","Give biometrics (fingerprints, iris, photo).","Collect the enrolment slip and track status online.","Download e-Aadhaar once generated."}','https://myaadhaar.uidai.gov.in/','myAadhaar (UIDAI)','Visit an Aadhaar Enrolment Centre (banks, post offices, government offices).',null,'Link Aadhaar with your bank account and mobile if the scheme uses Aadhaar-based payment (DBT).','all','https://uidai.gov.in/'),
('bank_passbook','Bank Account Passbook (Aadhaar-seeded)','வங்கி கணக்கு புத்தகம்','Any scheduled bank or India Post Payments Bank','Any resident; zero-balance accounts are available under PM Jan Dhan Yojana.','{"Aadhaar","Passport-size photograph","Mobile number"}','{"Visit a nearby bank branch or post office.","Ask to open a savings / Jan Dhan account.","Fill the account opening form with KYC documents.","Request Aadhaar seeding (linking) for DBT payments.","Collect the passbook."}','https://pmjdy.gov.in/','PM Jan Dhan Yojana','Visit any bank branch, Bank Mitra or post office.',null,'Ensure the account is active and Aadhaar-seeded so benefits can be credited.','all','https://pmjdy.gov.in/'),
('marksheets','Academic Mark Sheets','மதிப்பெண் சான்றிதழ்கள்','Board / University / Institution where you studied','Students who have completed the relevant exam.','{"Hall ticket / register number"}','{"Contact your school, college or the examination board.","For lost mark sheets, apply for a duplicate through the board or university office.","For CBSE, digital mark sheets are available through DigiLocker."}','https://www.digilocker.gov.in/','DigiLocker','Apply at the school/college office or the board''s regional office.',null,null,'all','https://www.digilocker.gov.in/'),
('bonafide_certificate','Bonafide / Study Certificate','படிப்புச் சான்றிதழ்','Your current school, college or institution','Currently enrolled students.','{"Student ID card","Fee receipt (if asked)"}','{"Submit a request to your institution office or principal.","Mention the purpose (e.g. scholarship).","Collect the signed and sealed certificate."}',null,null,'Request directly at your institution.',null,'Upload it on the scholarship portal; some portals need the institution to verify your application online too.','all',null),
('disability_certificate','Disability Certificate / UDID Card','மாற்றுத்திறனாளி சான்றிதழ்','Medical authority notified by the State, issued through the UDID system (Department of Empowerment of Persons with Disabilities)','Persons with a benchmark disability as assessed by the medical board.','{"Aadhaar","Recent photograph","Address proof","Existing medical records"}','{"Register on the Swavlamban (UDID) portal.","Fill in personal and disability details and upload documents.","Attend medical assessment at the assigned hospital.","Download the e-UDID card / certificate after approval."}','https://www.swavlambancard.gov.in/','UDID – Swavlamban Card','Visit the District Differently Abled Welfare Office or the designated government hospital.',null,null,'all','https://www.swavlambancard.gov.in/'),
('ration_card','Family / Smart Ration Card','குடும்ப அட்டை','Civil Supplies and Consumer Protection Department, Government of Tamil Nadu','Families residing in Tamil Nadu.','{"Aadhaar of all family members","Address proof","Photograph of head of family"}','{"Visit the TNPDS portal.","Choose apply for new smart card.","Enter family details and upload documents.","Officials verify; track status on the portal."}','https://www.tnpds.gov.in/','TNPDS','Apply at the Taluk Supply Office / Assistant Commissioner (Civil Supplies) office.',null,null,'TN','https://www.tnpds.gov.in/'),
('land_records','Land Records (Patta / Chitta)','பட்டா / சிட்டா','Revenue Department, Government of Tamil Nadu','Owners of agricultural land in Tamil Nadu.','{"Survey number","Owner name details"}','{"Open the TN e-Services land records portal.","Choose View Patta & FMB / Chitta.","Enter district, taluk, village and survey number.","Download the land record extract."}','https://eservices.tn.gov.in/','TN e-Services (Land Records)','Approach the Village Administrative Officer (VAO) or Taluk office.',null,null,'TN','https://eservices.tn.gov.in/'),
('birth_certificate','Birth Certificate','பிறப்புச் சான்றிதழ்','Local body registrar (Corporation / Municipality / Panchayat) under the Civil Registration System','Births registered in Tamil Nadu.','{"Hospital discharge details","Parents'' identity proof"}','{"Visit the Tamil Nadu birth and death registration portal.","Search the registration using date and place of birth.","Download the certificate if available."}','https://www.crstn.org/','CRS Tamil Nadu','Apply at the local body office where the birth was registered.',null,null,'TN','https://www.crstn.org/'),
('age_proof','Age Proof','வயதுச் சான்று','Varies – birth certificate, school certificate, or other officially accepted document','Anyone.','{}','{"Use a birth certificate, school transfer certificate or other document the scheme accepts."}',null,null,null,'Accepted alternatives are listed by each scheme; check the official scheme page.',null,'all',null),
('photo','Passport-size Photograph','புகைப்படம்','Self','Anyone.','{}','{"Take a recent passport-size colour photograph with a plain background."}',null,null,null,null,null,'all',null),
('project_report','Business Project Report','திட்ட அறிக்கை','Prepared by the applicant (help available from DIC / bank)','Entrepreneurs applying for loan-linked schemes.','{"Quotations for machinery","Estimated costs and revenues"}','{"Contact your District Industries Centre (DIC) for guidance.","Prepare a report with project cost, means of finance and expected income.","Attach it with your online application."}','https://www.msmeonline.tn.gov.in/','TN MSME Online','Visit the District Industries Centre (DIC).',null,null,'TN','https://www.msmeonline.tn.gov.in/'),
('employment_registration','Employment Exchange Registration','வேலைவாய்ப்பு பதிவு','Employment and Training Department, Government of Tamil Nadu','Job seekers residing in Tamil Nadu.','{"Educational certificates","Aadhaar","Community certificate (if applicable)"}','{"Open the TN Velaivaaippu portal.","Register with educational qualifications.","Download your registration card.","Renew the registration as required."}','https://tnvelaivaaippu.gov.in/','TN Velaivaaippu','Visit the District Employment Office.',null,null,'TN','https://tnvelaivaaippu.gov.in/'),
('pregnancy_registration','Pregnancy Registration (PICME number)','கர்ப்ப பதிவு (PICME)','Department of Public Health & Preventive Medicine, Government of Tamil Nadu','Pregnant women in Tamil Nadu.','{"Aadhaar","Ration card","Bank details"}','{"Register the pregnancy with the Village Health Nurse or at a government health centre.","Obtain the 12-digit PICME registration number.","Self-registration may be possible on the PICME portal."}','https://picme.tn.gov.in/','PICME','Register at the nearest Primary Health Centre or with the Village Health Nurse.',null,null,'TN','https://picme.tn.gov.in/');
